const cves = $('Query Unprocessed CVEs').all().map(i => i.json);
const inventory = $input.all().map(i => i.json);

if (cves.length === 0) {
  return [{ json: { _noMatches: true, processedCveDbIds: '', processedCount: 0 } }];
}

const processedCveDbIds = cves.map(c => c.id).join(',');

// ── CPE helpers ──────────────────────────────────────────────────────────────

function extractVulnerableCpes(configurations) {
  if (!configurations) return [];
  let cfg = configurations;
  if (typeof cfg === 'string') {
    try { cfg = JSON.parse(cfg); } catch(e) { return []; }
  }
  if (!Array.isArray(cfg)) {
    if (cfg && typeof cfg === 'object') {
      cfg = [cfg];
    } else {
      return [];
    }
  }
  cfg = cfg.filter(item => item !== null && item !== undefined);
  if (!cfg.length) return [];

  const entries = [];
  function walk(node) {
    if (!node || typeof node !== 'object') return;
    if (Array.isArray(node.cpeMatch)) {
      for (const m of node.cpeMatch) {
        if (m && m.vulnerable !== false) entries.push(m);
      }
    }
    if (Array.isArray(node.nodes)) {
      for (const child of node.nodes) walk(child);
    }
  }
  for (const top of cfg) {
    walk(top);
  }
  return entries;
}

function parseCpe(s) {
  if (!s) return null;
  const p = s.split(':');
  if (p.length < 6) return null;
  return { vendor: p[3], product: p[4], version: p[5] };
}

function cmpVer(a, b) {
  if (!a || !b || a === '*' || b === '*' || a === '-' || b === '-') return null;
  const clean = v => v.replace(/[^0-9.]/g, '.').split('.').map(Number).filter(n => !isNaN(n));
  const pa = clean(a), pb = clean(b);
  if (!pa.length || !pb.length) return null;
  const len = Math.max(pa.length, pb.length);
  for (let i = 0; i < len; i++) {
    const d = (pa[i] || 0) - (pb[i] || 0);
    if (d !== 0) return d;
  }
  return 0;
}

function matchCpe(invUri, entry) {
  const inv = parseCpe(invUri);
  const nvd = parseCpe(entry.criteria);
  if (!inv || !nvd) return null;

  if (invUri === entry.criteria) return 'HIGH';

  const vMatch = nvd.vendor === '*' || inv.vendor === nvd.vendor;
  const pMatch = nvd.product === '*' || inv.product === nvd.product;
  if (!vMatch || !pMatch) return null;

  const hasRange = entry.versionStartIncluding || entry.versionEndExcluding || entry.versionEndIncluding;
  if (hasRange && inv.version && inv.version !== '*') {
    let inRange = true;
    if (entry.versionStartIncluding) {
      const c = cmpVer(inv.version, entry.versionStartIncluding);
      if (c === null || c < 0) inRange = false;
    }
    if (inRange && entry.versionEndExcluding) {
      const c = cmpVer(inv.version, entry.versionEndExcluding);
      if (c === null || c >= 0) inRange = false;
    }
    if (inRange && entry.versionEndIncluding) {
      const c = cmpVer(inv.version, entry.versionEndIncluding);
      if (c === null || c > 0) inRange = false;
    }
    if (inRange) return 'HIGH';
  }

  if (nvd.version === '*' || nvd.version === '-') return 'MEDIUM';

  if (nvd.version && inv.version === nvd.version) return 'HIGH';

  return 'LOW';
}

// ── Main matching loop ───────────────────────────────────────────────────────

const matches = [];

for (const cve of cves) {
  const cpeEntries = extractVulnerableCpes(cve.configurations);
  if (!cpeEntries.length) continue;

  for (const inv of inventory) {
    let best = null;

    for (const entry of cpeEntries) {
      const conf = matchCpe(inv.cpe_uri, entry);
      if (!conf) continue;
      if (conf === 'HIGH') { best = 'HIGH'; break; }
      if (conf === 'MEDIUM' && best !== 'HIGH') best = 'MEDIUM';
      else if (conf === 'LOW' && !best) best = 'LOW';
    }

    if (best) {
      matches.push({
        json: {
          cve_db_id:              cve.id,
          software_id:            inv.id,
          correlation_confidence: best,
          _summary: { processedCveDbIds, processedCount: cves.length }
        }
      });
    }
  }
}

if (!matches.length) {
  return [{ json: { _noMatches: true, processedCveDbIds, processedCount: cves.length } }];
}

return matches;

const inserted = $input.all();
const firstMatch = $('Code CPE Match').first();
const summary = (firstMatch && firstMatch.json._summary) ? firstMatch.json._summary : {};

return [{
  json: {
    correlationsInserted: inserted.length,
    processedCveCount:    summary.processedCount    || 0,
    processedCveDbIds:    summary.processedCveDbIds || ''
  }
}];
